import { atom, read, update } from 'claude-code'
import type { ElementTable, EngineInterface, Register, RenderElement, Timer } from 'claude-code'

import type { GitDiffCommit, GitDiffFile, GitDiffPatch, GitDiffStat, GitDiffTimeline } from '../types'
import { branchCard, historyCard } from './card'
import type { CardNode } from './card'
import { EMPTY_TREE, LOG_LIMIT, loadBranchCompare, loadPatch, loadStat, loadTimeline } from './git'
import type { Loaded, Run } from './git'
import { ARROW_W, SLOT_W, dayLabels, formatTime, resolveStart, shortDate, stepStart, visibleCount } from './layout'
import {
  INITIAL,
  WORKING,
  buttonLabel,
  clickCommit,
  commitTitle,
  describeStat,
  diffSpec,
  merge,
  nodeIds,
  rangeCommits,
  refOf,
  selectionKey,
} from './model'

type Kit = Pick<ElementTable<'terminal'>, 'Box' | 'Text' | 'Button' | 'Code'> & {
  /** Absent on the phone. */
  Select: ElementTable<'terminal'>['Select'] | null
  /** The desktop's; the terminal draws the timeline in text. */
  Svg: ElementTable<'desktop'>['Svg'] | null
}

type Actions = {
  refresh: () => void
  details: () => void
  mode: (mode: GitDiffTimeline['mode']) => void
  pickCommit: (index: number) => void
  pickBranch: (side: 'base' | 'compare', name: string) => void
  swap: () => void
  step: (delta: number, count: number) => void
  toggleFile: (path: string) => void
}

const PANE = 'git-diff'
const PANE_ARGS = { id: PANE, title: 'Git Diff', rows: 24, columns: 96 } as const

/** Tools whose calls can change what git sees. */
const WATCHED = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Bash'])
const REFRESH_DELAY_MS = 1200
/** Files the files view lists, and diffs it holds open at once. */
const MAX_FILES = 100
const MAX_OPEN = 4
/** Commits the files view lists above the files. */
const MAX_COMMITS = 20
const BLOCKS = 5

const GRAY = '#9aa3b2'
const GREEN = '#2f9e5b'
const RED = '#d9534f'
const ACCENT = '#ff4d2e'

const timeline = atom({ plugin: 'git-diff-timeline', key: 'timeline' } as const, INITIAL)

/** `band`: the strip above the prompt. `pane`: the side pane, opened on its own. Set in register. */
let position: 'band' | 'pane' = 'band'

const errorText = (error: unknown) => (error instanceof Error ? error.message : String(error))

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

const kitOf = (ui: ElementTable): Kit => ({
  Box: ui.Box,
  Text: ui.Text,
  Button: ui.Button,
  Code: ui.Code,
  Select: 'Select' in ui ? ui.Select : null,
  Svg: 'Svg' in ui ? ui.Svg : null,
})

const runnerFor = async ($: EngineInterface): Promise<Run> => {
  const cwd = await $.session.cwd()

  return argv => $.process.run(argv, { cwd, timeoutMs: 15_000 })
}

/** The files open after a fresh read: the first file for a new pick, else those still changed. */
const openAfter = (cur: GitDiffTimeline, key: string, stat: GitDiffStat | null): string[] => {
  if (cur.statKey !== key) {
    const first = stat?.files[0]

    return first === undefined ? [] : [first.path]
  }

  const paths = new Set(stat?.files.map(file => file.path) ?? [])

  return cur.open.filter(path => paths.has(path))
}

/** Reads the diff of each open file still unread (`force`: every open file). */
const loadPatches = async ($: EngineInterface, force: boolean) => {
  const t = await read($, timeline)

  if (t.status !== 'ready' || t.stat === null) {
    return
  }

  const key = t.statKey
  const wanted = t.open.filter(path => force || !t.patches.some(patch => patch.path === path))

  if (wanted.length === 0) {
    return
  }

  const run = await runnerFor($)
  const spec = diffSpec(t)
  const loaded = await Promise.all(wanted.map(path => loadPatch(run, spec, path)))

  await update($, timeline, cur =>
    cur.statKey !== key
      ? cur
      : {
          ...cur,
          patches: [...cur.patches.filter(patch => !wanted.includes(patch.path)), ...loaded].filter(patch =>
            cur.open.includes(patch.path),
          ),
        },
  )
}

/** Reads what the pick changed, unless it is on screen already (`force` rereads), then its open files. */
const loadSelection = async ($: EngineInterface, force: boolean) => {
  const t = await read($, timeline)

  if (t.status !== 'ready') {
    return
  }

  const key = selectionKey(t)

  if (!force && t.statKey === key && t.stat !== null) {
    await loadPatches($, false)

    return
  }

  const run = await runnerFor($)
  let stat: GitDiffStat | null = null
  let statError = ''
  let branchCompare = t.branchCompare

  try {
    const [loadedStat, compared] = await Promise.all([
      loadStat(run, diffSpec(t)),
      t.mode === 'branches' ? loadBranchCompare(run, t.base, t.compare) : Promise.resolve(null),
    ])

    stat = loadedStat
    branchCompare = compared ?? branchCompare
  } catch (error) {
    statError = errorText(error)
  }

  await update($, timeline, cur =>
    selectionKey(cur) !== key
      ? cur
      : {
          ...cur,
          stat,
          statKey: key,
          statError,
          branchCompare: cur.mode === 'branches' ? branchCompare : cur.branchCompare,
          open: openAfter(cur, key, stat),
          patches: cur.statKey === key ? cur.patches : [],
        },
  )
  await loadPatches($, force)
}

const refresh = async ($: EngineInterface) => {
  const cwd = await $.session.cwd()
  const run = await runnerFor($)
  const failed = (error: unknown): Loaded => ({
    status: 'error',
    message: errorText(error),
    branch: '',
    commits: [],
    hasWorking: false,
    untracked: 0,
    baseOfOldest: '',
    branches: [],
    defaultBase: '',
  })
  const loaded = await loadTimeline(run).catch(failed)

  await update($, timeline, prev => merge(prev, loaded, cwd))
  await loadSelection($, true)
}

let pending: Timer | undefined

/** Whether the pane has been seated this session; a pane opened unasked can wait undrawn. */
let wasPlaced = false
let hasOffered = false

const openDetails = async ($: EngineInterface) => {
  try {
    wasPlaced = (await $.ui.open(PANE_ARGS)).isPlaced
  } catch {
    // /gitdiff says why when the pane cannot open.
  }
}

/** Shows what the person picked: the files view opened by their press, then a fresh read. */
const show = async ($: EngineInterface, change: (t: GitDiffTimeline) => GitDiffTimeline) => {
  await openDetails($)
  await update($, timeline, t => {
    const next = change(t)

    return selectionKey(next) === selectionKey(t)
      ? next
      : { ...next, stat: null, statKey: '', statError: '', open: [], patches: [] }
  })
  await loadSelection($, false)
}

const pickCommit = ($: EngineInterface, index: number) =>
  show($, t => ({ ...t, ...clickCommit(t, index), isPinned: true }))

const pickBranch = ($: EngineInterface, side: 'base' | 'compare', name: string) =>
  show($, t => (side === 'base' ? { ...t, base: name } : { ...t, compare: name }))

const toggleFile = async ($: EngineInterface, path: string) => {
  await update($, timeline, t => {
    if (t.open.includes(path)) {
      return { ...t, open: t.open.filter(p => p !== path), patches: t.patches.filter(patch => patch.path !== path) }
    }

    const open = [...t.open, path].slice(-MAX_OPEN)

    return { ...t, open, patches: t.patches.filter(patch => open.includes(patch.path)) }
  })
  await loadPatches($, false)
}

const step = ($: EngineInterface, delta: number, count: number) =>
  update($, timeline, t => ({ ...t, start: stepStart(t.start, delta, count, nodeIds(t).length) }))

const actionsFor = ($: EngineInterface): Actions => ({
  refresh: () => void refresh($).catch(() => undefined),
  details: () => void openDetails($),
  mode: mode => void show($, t => ({ ...t, mode })),
  pickCommit: index => void pickCommit($, index),
  pickBranch: (side, name) => void pickBranch($, side, name),
  swap: () => void show($, t => ({ ...t, base: t.compare, compare: t.base })),
  step: (delta, count) => void step($, delta, count),
  toggleFile: path => void toggleFile($, path),
})

/** A node in words: its pull request or message, `Uncommitted changes`, or what came before. */
const nodeName = (t: GitDiffTimeline, index: number) => {
  if (index < 0) {
    const oldest = t.commits[0]

    return t.baseOfOldest === EMPTY_TREE.sha1 || t.baseOfOldest === EMPTY_TREE.sha256 || oldest === undefined
      ? 'nothing (before the first commit)'
      : `before ${commitTitle(oldest)}`
  }

  const commit = t.commits[index]

  return commit === undefined ? 'Uncommitted changes' : commitTitle(commit)
}

const when = (seconds: number) => `${shortDate(seconds)}, ${formatTime(seconds)}`

/** What a click does next: wait for the second commit, or start a comparison. */
const clickHint = (t: GitDiffTimeline) => {
  const waiting = nodeIds(t).indexOf(t.anchor)

  return waiting < 0
    ? 'Click a commit to see its changes · click two to compare them'
    : `Click another commit to compare it with ${nodeName(t, waiting)}`
}

const rangeTitle = (t: GitDiffTimeline) =>
  t.mode === 'branches' ? `${t.base} ← ${t.compare}` : `${nodeName(t, t.from)} → ${nodeName(t, t.to)}`

const roleOf = (t: GitDiffTimeline, index: number): CardNode['role'] =>
  index === t.to ? 'compare' : index === t.from ? 'base' : index > t.from && index < t.to ? 'between' : 'outside'

/** The window of commits the strip shows: where it starts and how many. */
const windowOf = (t: GitDiffTimeline, columns: number) => {
  const total = nodeIds(t).length
  const count = visibleCount(columns, total)
  const start = resolveStart(t.start, count, total)

  return { total, count, start, indexes: Array.from({ length: Math.min(count, total) }, (_, i) => start + i) }
}

const branchOptions = (t: GitDiffTimeline) =>
  t.branches.map(branch => ({
    value: branch.name,
    label: branch.name === t.branch ? `${branch.name} (current)` : branch.name,
  }))

/** The strip's first row: History or Branches, how to pick, the files view and a refresh. */
const controls = ({ Box, Text, Button, Select }: Kit, t: GitDiffTimeline, on: Actions): RenderElement => {
  const isHistory = t.mode === 'history'
  const pickers = isHistory ? (
    <Text dimColor>{clickHint(t)}</Text>
  ) : Select === null ? null : t.branches.length === 0 ? (
      <Text dimColor>No branches to compare.</Text>
    ) : (
      <Box flexDirection="row" columnGap={1} alignItems="center" flexWrap="wrap">
        <Select
          key="branch-base"
          label="Base"
          options={branchOptions(t)}
          value={t.base}
          onSelect={name => on.pickBranch('base', name)}
        />
        <Text dimColor>←</Text>
        <Select
          key="branch-compare"
          label="Compare"
          options={branchOptions(t)}
          value={t.compare}
          onSelect={name => on.pickBranch('compare', name)}
        />
        <Button key="swap" plain label="⇄" onPress={on.swap} />
      </Box>
    )

  return (
    <Box flexDirection="row" flexWrap="wrap" columnGap={1} alignItems="center" justifyContent="space-between">
      <Box flexDirection="row" columnGap={1} alignItems="center" flexWrap="wrap">
        <Button
          key="mode:history"
          label="History"
          {...(isHistory ? { variant: 'primary' as const } : {})}
          onPress={() => on.mode('history')}
        />
        <Button
          key="mode:branches"
          label="Branches"
          {...(isHistory ? {} : { variant: 'primary' as const })}
          onPress={() => on.mode('branches')}
        />
        {pickers}
      </Box>
      <Box flexDirection="row" columnGap={1}>
        <Button key="details" label="Files changed" onPress={on.details} />
        <Button key="refresh" plain label="↻" onPress={on.refresh} />
      </Box>
    </Box>
  )
}

/** The totals as text: the terminal's strip, and the files view's first line. */
const totals = ({ Box, Text }: Kit, t: GitDiffTimeline): RenderElement => {
  const stat = describeStat(t.stat)

  return (
    <Box flexDirection="row" columnGap={1}>
      {t.statError !== '' && <Text color={RED}>{t.statError}</Text>}
      {t.statError === '' && stat === null && <Text dimColor>Reading the diff…</Text>}
      {stat !== null && <Text>{stat.files}</Text>}
      {stat !== null && <Text color={GREEN}>{stat.added}</Text>}
      {stat !== null && <Text color={RED}>{stat.deleted}</Text>}
    </Box>
  )
}

const dotColor = (role: CardNode['role']) =>
  role === 'base' || role === 'compare' ? { color: ACCENT } : role === 'between' ? {} : { color: GRAY }

/** History: the card (a line of dots in text on the terminal), and under it a button per commit. */
const historyStrip = (kit: Kit, t: GitDiffTimeline, columns: number, on: Actions): RenderElement => {
  const { Box, Text, Button, Svg } = kit
  const { total, count, start, indexes } = windowOf(t, columns)
  const labels = dayLabels(indexes.map(i => t.commits[i]?.time ?? null))
  const nodes: CardNode[] = indexes.map((i, k) => {
    const commit = t.commits[i]

    return commit === undefined
      ? { label: 'Now', churn: 0, role: roleOf(t, i), isWorking: true, tip: 'Uncommitted changes' }
      : {
          label: labels[k] ?? '',
          churn: commit.added + commit.deleted,
          role: roleOf(t, i),
          isWorking: false,
          tip: `${commit.short} · ${commitTitle(commit)} · +${commit.added} −${commit.deleted}`,
        }
  })
  const title = `${t.branch} · ${plural(t.commits.length, 'commit')}${t.commits.length >= LOG_LIMIT ? ' shown' : ''}`
  const picture =
    Svg === null ? (
      <Box flexDirection="column">
        {totals(kit, t)}
        <Box flexDirection="row">
          <Box width={ARROW_W} />
          {nodes.map(node => (
            <Box width={SLOT_W} justifyContent="center">
              <Text {...dotColor(node.role)} bold={node.role === 'compare'}>
                {node.isWorking ? '○' : node.role === 'compare' ? '◉' : '●'}
              </Text>
            </Box>
          ))}
        </Box>
      </Box>
    ) : (
      <Svg
        source={historyCard({
          columns,
          nodes,
          title,
          stats: describeStat(t.stat),
          older: start,
          newer: total - start - indexes.length,
        })}
        alt={`${title}: ${rangeTitle(t)}`}
      />
    )

  return (
    <Box flexDirection="column">
      {picture}
      <Box flexDirection="row">
        <Box width={ARROW_W}>
          <Button key="prev" plain dimColor={start === 0} label="‹" onPress={() => on.step(-1, count)} />
        </Box>
        {indexes.map(i => {
          const commit = t.commits[i]
          const role = roleOf(t, i)
          const look =
            role === 'compare'
              ? { variant: 'primary' as const }
              : role === 'base'
                ? { variant: 'secondary' as const }
                : { plain: true as const, dimColor: role === 'outside' }

          return (
            <Box width={SLOT_W} justifyContent="center">
              <Button
                key={`node:${i}`}
                label={commit === undefined ? 'Now' : buttonLabel(commit)}
                {...look}
                onPress={() => on.pickCommit(i)}
              />
            </Box>
          )
        })}
        <Box width={ARROW_W} justifyContent="flex-end">
          <Button key="next" plain dimColor={start + count >= total} label="›" onPress={() => on.step(1, count)} />
        </Box>
      </Box>
      {messageRow(kit, t, t.from, '○')}
      {messageRow(kit, t, t.to, '●')}
    </Box>
  )
}

/** One end of the comparison: its mark, short sha, message and when. */
const messageRow = ({ Box, Text }: Kit, t: GitDiffTimeline, index: number, mark: string): RenderElement => {
  const commit = t.commits[index]
  const short = index < 0 ? t.baseOfOldest.slice(0, 7) : (commit?.short ?? '')

  return (
    <Box flexDirection="row" columnGap={1}>
      <Text color={ACCENT}>{mark}</Text>
      {short !== '' && <Text dimColor>{short}</Text>}
      <Box flexShrink={1}>
        <Text wrap="truncate-end">{nodeName(t, index)}</Text>
      </Box>
      {commit !== undefined && <Text dimColor>{when(commit.time)}</Text>}
    </Box>
  )
}

/** Branches: the fork card, or a line of words on the terminal. */
const branchStrip = (kit: Kit, t: GitDiffTimeline, columns: number): RenderElement => {
  const { Box, Text, Svg } = kit
  const compared = t.branchCompare
  const ahead = compared?.ahead ?? 0
  const behind = compared?.behind ?? 0
  const words = `${t.compare} is ${plural(ahead, 'commit')} ahead, ${behind} behind ${t.base}`

  if (Svg === null) {
    return (
      <Box flexDirection="column">
        <Text>{words}</Text>
        {totals(kit, t)}
      </Box>
    )
  }

  const mergeBase = compared?.mergeBase ?? null

  return (
    <Svg
      source={branchCard({
        columns,
        base: t.base,
        compare: t.compare,
        ahead,
        behind,
        aheadTips: compared?.aheadCommits.map(commitTitle) ?? [],
        behindTips: compared?.behindCommits.map(commitTitle) ?? [],
        mergeBase: mergeBase === null ? '' : `merge base ${mergeBase.short} · ${shortDate(mergeBase.time)}`,
        stats: describeStat(t.stat),
      })}
      alt={words}
    />
  )
}

const strip = (kit: Kit, t: GitDiffTimeline, columns: number, on: Actions): RenderElement => {
  const { Box } = kit

  return (
    <Box flexDirection="column">
      {controls(kit, t, on)}
      {t.mode === 'history' ? historyStrip(kit, t, columns, on) : branchStrip(kit, t, columns)}
    </Box>
  )
}

/** GitHub's five squares: a file's share of lines added and deleted. */
const blocks = (file: GitDiffFile) => {
  const total = (file.added ?? 0) + (file.deleted ?? 0)

  if (file.added === null || total === 0) {
    return { added: 0, deleted: 0 }
  }

  const added = Math.round((file.added / total) * BLOCKS)

  return { added, deleted: BLOCKS - added }
}

const patchView = ({ Box, Text, Code }: Kit, path: string, patch: GitDiffPatch | undefined): RenderElement => {
  if (patch === undefined) {
    return <Text dimColor>Loading the diff…</Text>
  }

  if (patch.note === 'binary') {
    return <Text dimColor>Binary file not shown.</Text>
  }

  if (patch.note === 'empty') {
    return <Text dimColor>No line changes: the file's mode or name changed.</Text>
  }

  if (patch.note !== '') {
    return <Text color={RED}>{patch.note}</Text>
  }

  return (
    <Box flexDirection="column">
      <Code source={patch.hunks} format="diff" path={path} />
      {patch.isCut && <Text dimColor>Diff cut to fit here; open the file to see the rest.</Text>}
    </Box>
  )
}

const fileRow = (kit: Kit, t: GitDiffTimeline, file: GitDiffFile, on: Actions): RenderElement => {
  const { Box, Text, Button } = kit
  const isOpen = t.open.includes(file.path)
  const share = blocks(file)
  const rest = BLOCKS - share.added - share.deleted

  return (
    <Box flexDirection="column">
      <Box flexDirection="row" columnGap={1}>
        <Button
          key={`file:${file.path}`}
          plain
          label={`${isOpen ? '▾' : '▸'} ${file.path}`}
          onPress={() => on.toggleFile(file.path)}
        />
        <Text color={GREEN}>{file.added === null ? 'binary' : `+${file.added}`}</Text>
        {file.deleted !== null && <Text color={RED}>{`−${file.deleted}`}</Text>}
        <Box flexDirection="row">
          {share.added > 0 && <Text color={GREEN}>{'■'.repeat(share.added)}</Text>}
          {share.deleted > 0 && <Text color={RED}>{'■'.repeat(share.deleted)}</Text>}
          {rest > 0 && <Text dimColor>{'■'.repeat(rest)}</Text>}
        </Box>
      </Box>
      {isOpen && patchView(kit, file.path, t.patches.find(patch => patch.path === file.path))}
    </Box>
  )
}

const notice = ({ Text }: Kit, t: GitDiffTimeline): RenderElement => {
  switch (t.status) {
    case 'loading':
      return <Text dimColor>Reading git history…</Text>
    case 'no-repo':
      return <Text dimColor>{`Not a git repository: ${t.cwd}`}</Text>
    case 'error':
      return <Text color={RED}>{`git failed: ${t.message}`}</Text>
    default:
      return <Text dimColor>{t.message}</Text>
  }
}

/** One commit of a comparison: short sha, message and when, and the body's first line under it. */
const commitRow = ({ Box, Text }: Kit, commit: GitDiffCommit): RenderElement => {
  const title = commitTitle(commit)
  const detail = commit.body
    .split('\n')
    .map(line => line.trim())
    .find(line => line !== '' && !title.includes(line) && !line.startsWith('See merge request'))

  return (
    <Box flexDirection="column">
      <Box flexDirection="row" columnGap={1}>
        <Text dimColor>{commit.short}</Text>
        <Box flexShrink={1}>
          <Text wrap="truncate-end">{title}</Text>
        </Box>
        <Text dimColor>{when(commit.time)}</Text>
      </Box>
      {detail !== undefined && (
        <Box paddingLeft={8}>
          <Text dimColor wrap="truncate-end">
            {detail}
          </Text>
        </Box>
      )}
    </Box>
  )
}

/** The commits the comparison takes in, newest first, as GitHub's compare page lists them. */
const commitList = (kit: Kit, t: GitDiffTimeline): RenderElement | null => {
  const { Box, Text } = kit
  const commits =
    t.mode === 'history' ? rangeCommits(t) : [...(t.branchCompare?.aheadCommits ?? [])].reverse()
  const total = t.mode === 'history' ? commits.length : (t.branchCompare?.ahead ?? commits.length)

  if (commits.length === 0) {
    return null
  }

  return (
    <Box flexDirection="column">
      <Text bold>{t.mode === 'history' ? plural(total, 'commit') : `${plural(total, 'commit')} on ${t.compare}`}</Text>
      {commits.slice(0, MAX_COMMITS).map(commit => commitRow(kit, commit))}
      {total > MAX_COMMITS && <Text dimColor>{`… ${total - MAX_COMMITS} older not listed`}</Text>}
    </Box>
  )
}

/** The files view: the commits compared, then what changed, file by file, as GitHub shows it. */
const filesView = (kit: Kit, t: GitDiffTimeline, on: Actions): RenderElement => {
  const { Box, Text } = kit
  const files = t.stat?.files ?? []
  const more = files.length - MAX_FILES
  const compared = t.branchCompare

  return (
    <Box flexDirection="column" rowGap={1}>
      {t.mode === 'branches' && compared !== null && (
        <Text dimColor>
          {`${t.compare} is ${plural(compared.ahead, 'commit')} ahead, ${compared.behind} behind ${t.base}` +
            (compared.mergeBase === null ? ' · no shared history' : ` · they split at ${compared.mergeBase.short}`)}
        </Text>
      )}
      {commitList(kit, t)}
      {totals(kit, t)}
      {files.slice(0, MAX_FILES).map(file => fileRow(kit, t, file, on))}
      {more > 0 && <Text dimColor>{`… ${plural(more, 'more file')} not listed`}</Text>}
      {t.mode === 'history' && refOf(t, t.to) === WORKING && t.untracked > 0 && (
        <Text dimColor>{`${plural(t.untracked, 'untracked file')} not in this diff`}</Text>
      )}
    </Box>
  )
}

const paneView = (kit: Kit, t: GitDiffTimeline, bodyColumns: number, on: Actions): RenderElement => {
  const { Box, Text, Button } = kit
  const isReady = t.status === 'ready'

  return (
    <Box flexDirection="column" paddingX={1} rowGap={1}>
      <Box flexDirection="row" justifyContent="space-between">
        <Box flexDirection="row" columnGap={1} flexShrink={1}>
          <Text bold>Files changed</Text>
          {isReady && (
            <Box flexShrink={1}>
              <Text dimColor wrap="truncate-end">
                {rangeTitle(t)}
              </Text>
            </Box>
          )}
        </Box>
        {position === 'band' && <Button key="refresh" plain label="↻" onPress={on.refresh} />}
      </Box>
      {isReady && position === 'pane' && strip(kit, t, bodyColumns - 2, on)}
      {isReady ? filesView(kit, t, on) : notice(kit, t)}
    </Box>
  )
}

/** The strip is always on screen in a repository; the pane only counts while it is open. */
const refreshIfShown = async ($: EngineInterface) => {
  try {
    if (position === 'band' || (await $.ui.panes()).some(pane => pane.id === PANE)) {
      await refresh($)
    }
  } catch {
    // The view keeps its last good state; the next trigger tries again.
  }
}

/** One refresh per burst of tool calls, after the burst settles. */
const scheduleRefresh = ($: EngineInterface) => {
  if (pending !== undefined) {
    return
  }

  pending = $.clock.after(REFRESH_DELAY_MS, () => {
    pending = undefined
    void refreshIfShown($)
  })
}

const begin = async ($: EngineInterface) => {
  try {
    await refresh($)

    if (position === 'band') {
      // The strip replaces the side pane: close one an earlier load or setting left open.
      await $.ui.close({ id: PANE })

      return
    }

    const { status } = await read($, timeline)

    if (status !== 'no-repo' && status !== 'error') {
      wasPlaced = (await $.ui.open(PANE_ARGS)).isPlaced
    }
  } catch {
    // Opening the pane by hand (/gitdiff) shows the error.
  }
}

/**
 * A pane opened at session start is unasked, and a desktop that has not attached yet
 * seats it late or never. The first prompt of a repository session asks again: opened
 * with the person's prompt behind it, it is seated at any width.
 */
const offerOnce = async ($: EngineInterface) => {
  if (position !== 'pane' || hasOffered) {
    return
  }

  try {
    const { status } = await read($, timeline)

    if (status === 'loading') {
      return
    }

    hasOffered = true

    if (!wasPlaced && status !== 'no-repo' && status !== 'error') {
      wasPlaced = (await $.ui.open(PANE_ARGS)).isPlaced
    }
  } catch {
    // The pane stays as it was; /gitdiff opens it by hand.
  }
}

export const register: Register = (on, options) => {
  position = options.position === 'pane' ? 'pane' : 'band'

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'gitdiff', description: 'Open the Git Diff files view (what changed, file by file)' })
    void begin($)

    return next(e)
  })

  on('command.run', { command: 'gitdiff' }, async $ => {
    await refresh($).catch(() => undefined)

    const opened = await $.ui.open(PANE_ARGS)

    wasPlaced = opened.isPlaced

    return { text: opened.isPlaced ? 'Git Diff pane opened.' : `Git Diff pane is waiting: ${opened.reason}` }
  })

  on('prompt.submit', async ($, e, next) => {
    await offerOnce($)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)

    scheduleRefresh($)

    return done
  })

  on('tool.call', async ($, e, next) => {
    const ran = await next(e)

    if (WATCHED.has(e.tool)) {
      scheduleRefresh($)
    }

    return ran
  })

  // The strip above the prompt: drawn in a repository, left alone elsewhere.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (position !== 'band' || e.props.hasSurvey) {
      return next(e)
    }

    const t = await read($, timeline)

    if (t.status !== 'ready' && t.status !== 'error') {
      return next(e)
    }

    const kit = kitOf($.ui.resolve(e))
    const { Text } = kit

    return t.status === 'ready' ? (
      strip(kit, t, e.props.bodyColumns, actionsFor($))
    ) : (
      <Text color={RED}>{`Git Diff: git failed: ${t.message}`}</Text>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const t = await read($, timeline)

    return paneView(kitOf($.ui.resolve(e)), t, e.props.bodyColumns, actionsFor($))
  })
}

files.hooks/card.ts:
import { slotCenter } from './layout'

/**
 * The cards the desktop draws as one Svg each: a deep navy card, the compared span
 * aglow in orange-red. Units are tenths of a cell, so a dot drawn at a slot's centre
 * sits over the commit button in that slot below the card.
 */

/** viewBox units per cell: a card is `columns * CELL` wide. */
export const CELL = 10

const H = 170
const BY = 116
const WAVE = 50
const MAX_DOTS = 12

const CARD = '#0f1729'
const INK = '#eef1f7'
const INK2 = '#a3adc2'
const MUTED = '#8a94ab'
const LINE = '#2a3550'
const DOT = '#56627f'
const IN_RANGE = '#c9d1e3'
const ADDED = '#5fd38d'
const DELETED = '#ff7b8a'
const A1 = '#ffa25c'
const A2 = '#ff4d2e'
const FONT = 'Segoe UI, system-ui, -apple-system, sans-serif'

export type CardNode = {
  /** Under the dot: `Jul 4`, `Now`. */
  label: string
  /** Lines changed: the wave's height over the dot. */
  churn: number
  role: 'outside' | 'base' | 'between' | 'compare'
  isWorking: boolean
  /** What the dot is, for a reader that hovers or cannot see it. */
  tip: string
}

export type CardStats = { files: string; added: string; deleted: string } | null

export type HistoryCardInput = {
  /** The band's width in cells: the card spans it. */
  columns: number
  /** The commits in view, oldest first, one per slot. */
  nodes: CardNode[]
  title: string
  stats: CardStats
  /** Commits beyond the view on each side. */
  older: number
  newer: number
}

export type BranchCardInput = {
  columns: number
  base: string
  compare: string
  ahead: number
  behind: number
  /** Titles of each side's commits, oldest first. */
  aheadTips: string[]
  behindTips: string[]
  /** Under the fork: `merge base · Jul 13`; '' when the branches share no history. */
  mergeBase: string
  stats: CardStats
}

const r = (n: number) => Math.round(n * 10) / 10

const esc = (text: string) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** A smooth curve through the points (Catmull-Rom as cubic Béziers). */
const smooth = (points: ReadonlyArray<readonly [number, number]>) => {
  const [x0 = 0, y0 = 0] = points[0] ?? []
  let d = `M${r(x0)},${r(y0)}`

  for (let i = 0; i < points.length - 1; i += 1) {
    const a = points[i - 1] ?? points[i]!
    const b = points[i]!
    const c = points[i + 1]!
    const e = points[i + 2] ?? c

    d += ` C${r(b[0] + (c[0] - a[0]) / 7)},${r(b[1] + (c[1] - a[1]) / 7)} ${r(c[0] - (e[0] - b[0]) / 7)},${r(c[1] - (e[1] - b[1]) / 7)} ${r(c[0])},${r(c[1])}`
  }

  return d
}

const open = (width: number, label: string, glowX1: number, glowX2: number) =>
  [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${H}" width="${width * 4}" height="${H * 4}" font-family="${FONT}" role="img" aria-label="${esc(label)}">`,
    '<defs>',
    '<linearGradient id="bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#151f37"/><stop offset="1" stop-color="#0b1220"/></linearGradient>',
    `<linearGradient id="accent" gradientUnits="userSpaceOnUse" x1="${r(glowX1)}" y1="0" x2="${r(Math.max(glowX2, glowX1 + 1))}" y2="0"><stop offset="0" stop-color="${A1}"/><stop offset="1" stop-color="${A2}"/></linearGradient>`,
    `<linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${A2}" stop-opacity="0.5"/><stop offset="1" stop-color="${A2}" stop-opacity="0"/></linearGradient>`,
    `<radialGradient id="halo"><stop offset="0" stop-color="${A2}" stop-opacity="0.22"/><stop offset="1" stop-color="${A2}" stop-opacity="0"/></radialGradient>`,
    '<filter id="glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>',
    '</defs>',
    `<rect width="${width}" height="${H}" rx="22" fill="url(#bg)"/>`,
  ].join('')

/** The header's right side: the totals, or that they are on their way. */
const statsText = (x: number, stats: CardStats) =>
  stats === null
    ? `<text x="${r(x)}" y="30" font-size="15" fill="${MUTED}" text-anchor="end">reading the diff…</text>`
    : `<text x="${r(x)}" y="30" font-size="15" text-anchor="end"><tspan fill="${INK}">${esc(stats.files)}</tspan><tspan dx="14" fill="${ADDED}">${esc(stats.added)}</tspan><tspan dx="10" fill="${DELETED}">${esc(stats.deleted)}</tspan></text>`

const glowDot = (x: number, y: number, extra = '') =>
  `<circle cx="${r(x)}" cy="${y}" r="17" fill="${A2}" opacity="0.35" filter="url(#glow)"/><circle${extra} cx="${r(x)}" cy="${y}" r="8" fill="${A2}" stroke="${CARD}" stroke-width="3"/>`

const nodeMark = (node: CardNode, i: number, x: number) => {
  const at = ` data-node="${i}" cx="${r(x)}" cy="${BY}"`
  const role = ` data-role="${node.role}"`
  const dashed = node.isWorking ? ' stroke-dasharray="3 3"' : ''

  switch (node.role) {
    case 'compare':
      return `<circle cx="${r(x)}" cy="${BY}" r="17" fill="${A2}" opacity="0.35" filter="url(#glow)"/><circle${at} r="8"${role} fill="${A2}" stroke="${CARD}" stroke-width="3"/>`
    case 'base':
      return `<circle${at} r="7"${role} fill="${CARD}" stroke="${A1}" stroke-width="3"${dashed}/>`
    case 'between':
      return `<circle${at} r="4.5"${role} fill="${IN_RANGE}"/>`
    default:
      return node.isWorking
        ? `<circle${at} r="5"${role} fill="${CARD}" stroke="${IN_RANGE}" stroke-width="2"${dashed}/>`
        : `<circle${at} r="4.5"${role} fill="${DOT}"/>`
  }
}

/** History: the commits in view on a line, the wave of their size above it, the pick aglow. */
export const historyCard = ({ columns, nodes, title, stats, older, newer }: HistoryCardInput): string => {
  const width = columns * CELL
  const xs = nodes.map((_, i) => slotCenter(i) * CELL)
  const tallest = Math.log10(1 + Math.max(1, ...nodes.map(node => node.churn)))
  const ys = nodes.map(node => BY - 6 - (WAVE * Math.log10(1 + node.churn)) / tallest)
  const left = 16
  const right = width - 16
  const wave = smooth([[left, BY], ...xs.map((x, i) => [x, ys[i]!] as const), [right, BY]])
  const area = `${wave} L${right},${BY} L${left},${BY} Z`
  const picked = nodes.map((node, i) => (node.role === 'outside' ? -1 : i)).filter(i => i >= 0)
  const firstPicked = picked[0]
  const lastPicked = picked[picked.length - 1]
  const hasSpan = firstPicked !== undefined && lastPicked !== undefined
  // A pick that runs out of view glows to the card's edge on that side.
  const spanFrom = !hasSpan ? 0 : nodes[firstPicked]!.role === 'between' ? left : xs[firstPicked]!
  const spanTo = !hasSpan ? 0 : nodes[lastPicked]!.role === 'between' ? right : xs[lastPicked]!
  const parts = [
    open(width, title, spanFrom, spanTo),
    hasSpan ? `<ellipse cx="${r((spanFrom + spanTo) / 2)}" cy="${BY - 30}" rx="${r(Math.max(120, (spanTo - spanFrom) / 2 + 80))}" ry="90" fill="url(#halo)"/>` : '',
    `<text x="24" y="30" font-size="15" fill="${INK2}">${esc(title)}</text>`,
    statsText(width - 24, stats),
    `<path d="${area}" fill="#18233c"/>`,
    `<path d="${wave}" fill="none" stroke="#2f3d5c" stroke-width="2"/>`,
  ]

  if (hasSpan && spanTo > spanFrom) {
    parts.push(
      `<clipPath id="span"><rect x="${r(spanFrom)}" y="0" width="${r(spanTo - spanFrom)}" height="${H}"/></clipPath>`,
      `<g clip-path="url(#span)"><path d="${area}" fill="url(#fill)"/><path d="${wave}" fill="none" stroke="url(#accent)" stroke-width="3" filter="url(#glow)"/></g>`,
    )
  }

  parts.push(`<line x1="${left}" y1="${BY}" x2="${right}" y2="${BY}" stroke="${LINE}" stroke-width="3" stroke-linecap="round"/>`)

  if (hasSpan && spanTo > spanFrom) {
    parts.push(
      `<line x1="${r(spanFrom)}" y1="${BY}" x2="${r(spanTo)}" y2="${BY}" stroke="url(#accent)" stroke-width="5" stroke-linecap="round" filter="url(#glow)"/>`,
    )
  }

  nodes.forEach((node, i) => {
    const x = xs[i]!
    const isPicked = node.role === 'base' || node.role === 'compare'

    parts.push(
      `<g><title>${esc(node.tip)}</title>${nodeMark(node, i, x)}</g>`,
      `<text x="${r(x)}" y="146" font-size="13" fill="${isPicked ? INK : MUTED}" text-anchor="middle">${esc(node.label)}</text>`,
    )
  })

  if (older > 0) {
    parts.push(`<text x="20" y="164" font-size="12" fill="${MUTED}">‹ ${older} older</text>`)
  }

  if (newer > 0) {
    parts.push(`<text x="${width - 20}" y="164" font-size="12" fill="${MUTED}" text-anchor="end">${newer} newer ›</text>`)
  }

  parts.push('</svg>')

  return parts.join('')
}

/** Spreads `count` dots from `x1` to `x2`, the last one at `x2`. */
const spread = (count: number, x1: number, x2: number) =>
  Array.from({ length: count }, (_, i) => (count === 1 ? x2 : x1 + ((x2 - x1) * i) / (count - 1)))

/** Branches: the base line, the compare branch forking off it, each side's commits as dots. */
export const branchCard = (input: BranchCardInput): string => {
  const { columns, base, compare, ahead, behind, aheadTips, behindTips, mergeBase, stats } = input
  const width = columns * CELL
  const fork = Math.round(width * 0.22)
  const top = 68
  const tipX = width - 40
  const aheadCount = Math.min(ahead, MAX_DOTS)
  const behindCount = Math.min(behind, MAX_DOTS)
  const aheadXs = spread(aheadCount, fork + 90, tipX)
  const behindXs = spread(behindCount, fork + 90, tipX)
  const label = `${compare} is ${ahead} ahead of and ${behind} behind ${base}`
  const parts = [
    open(width, label, fork, tipX),
    `<ellipse cx="${r((fork + tipX) / 2)}" cy="${top}" rx="${r((tipX - fork) / 2 + 60)}" ry="70" fill="url(#halo)"/>`,
    `<text x="24" y="30" font-size="15"><tspan fill="${INK}">${ahead} ahead</tspan><tspan dx="8" fill="${MUTED}">·</tspan><tspan dx="8" fill="${INK}">${behind} behind</tspan></text>`,
    statsText(width - 24, stats),
    `<line x1="16" y1="${BY}" x2="${width - 16}" y2="${BY}" stroke="${LINE}" stroke-width="3" stroke-linecap="round"/>`,
    ...[0.25, 0.5, 0.75].map(at => `<circle cx="${r(fork * at)}" cy="${BY}" r="4.5" fill="${DOT}"/>`),
  ]

  behindXs.forEach((x, i) => {
    const tip = behindTips[behindTips.length - behindCount + i] ?? ''
    const isTip = i === behindCount - 1

    parts.push(
      `<g><title>${esc(tip)}</title><circle data-side="behind" cx="${r(x)}" cy="${BY}" r="${isTip ? 6 : 4.5}" fill="${isTip ? IN_RANGE : DOT}"/></g>`,
    )
  })

  if (ahead > 0) {
    parts.push(
      `<path d="M${fork},${BY} C${fork + 40},${BY} ${fork + 36},${top} ${fork + 76},${top} L${tipX},${top}" fill="none" stroke="url(#accent)" stroke-width="3" stroke-linecap="round" filter="url(#glow)"/>`,
    )
  }

  aheadXs.forEach((x, i) => {
    const tip = aheadTips[aheadTips.length - aheadCount + i] ?? ''
    const isTip = i === aheadCount - 1

    parts.push(
      `<g><title>${esc(tip)}</title>${isTip ? glowDot(x, top, ' data-side="ahead"') : `<circle data-side="ahead" cx="${r(x)}" cy="${top}" r="4" fill="#ffc6a6"/>`}</g>`,
    )
  })

  if (ahead > aheadCount) {
    parts.push(`<text x="${fork + 90}" y="${top - 16}" font-size="12" fill="${MUTED}">+${ahead - aheadCount} more</text>`)
  }

  if (behind > behindCount) {
    parts.push(`<text x="${fork + 90}" y="${BY + 22}" font-size="12" fill="${MUTED}">+${behind - behindCount} more</text>`)
  }

  parts.push(
    `<circle cx="${fork}" cy="${BY}" r="7" fill="${CARD}" stroke="${IN_RANGE}" stroke-width="2.5"/>`,
    `<text x="${tipX}" y="${top - 18}" font-size="14" fill="${INK2}" text-anchor="end">${esc(compare)}</text>`,
    `<text x="${tipX}" y="${BY + 26}" font-size="14" fill="${INK2}" text-anchor="end">${esc(base)}</text>`,
    mergeBase === '' ? '' : `<text x="${fork}" y="${BY + 26}" font-size="12" fill="${MUTED}" text-anchor="middle">${esc(mergeBase)}</text>`,
    '</svg>',
  )

  return parts.join('')
}

files.hooks/git.ts:
import type {
  GitDiffBranch,
  GitDiffBranchCompare,
  GitDiffCommit,
  GitDiffFile,
  GitDiffPatch,
  GitDiffStat,
} from '../types'

export type Run = (
  argv: readonly string[],
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

export type Loaded = {
  status: 'ready' | 'no-repo' | 'no-commits' | 'error'
  message: string
  branch: string
  commits: GitDiffCommit[]
  hasWorking: boolean
  untracked: number
  baseOfOldest: string
  branches: GitDiffBranch[]
  /** The branch others are compared with by default: origin's default branch, else a main one. */
  defaultBase: string
}

/** The revisions of one `git diff`: two, one (against the working tree), or `base...compare`. */
export type Spec = readonly string[]

export const LOG_LIMIT = 60
export const BRANCH_COMMITS = 30
/** Characters of hunks one file's diff may hold: a Code element takes at most 10000. */
export const PATCH_LIMIT = 9000

/** The tree with nothing in it, which a root commit is compared with. */
export const EMPTY_TREE = {
  sha1: '4b825dc642cb6eb9a060e54bf8d69288fbee4904',
  sha256: '6ef19b41225c5369f1c104d45d8d85efa9b057b53b14b4b9b939dd74decc5321',
} as const

/** Characters of a commit message's body kept: enough for a pull request's title and a line or two. */
const BODY_LIMIT = 300

const RS = '\u001e'
const US = '\u001f'
const GS = '\u001d'
const LOG_FORMAT = '--format=%x1e%H%x1f%h%x1f%ct%x1f%s%x1f%b%x1d'
const REF_FORMAT = '--format=%(refname)%1f%(refname:short)%1f%(committerdate:unix)%1f%(symref)'
const NUMSTAT = ['diff', '--numstat', '-z', '--no-renames']
const PATCH = ['diff', '--no-color', '--no-ext-diff', '--no-renames', '-U3']
const MAIN_BRANCHES = ['origin/main', 'origin/master', 'main', 'master']
/** Control characters a Code element refuses: all but tab and newline. */
const CONTROL = /[\u0000-\u0008\u000b-\u001f\u007f]/g

const firstLine = (text: string) => text.trim().split(/\r?\n/)[0] ?? ''

const countOf = (text: string, pattern: RegExp) => Number(pattern.exec(text)?.[1] ?? 0)

/** `git log` with LOG_FORMAT and `--shortstat`: newest first in, oldest first out. */
export const parseLog = (stdout: string): GitDiffCommit[] =>
  stdout
    .split(RS)
    .filter(chunk => chunk.trim() !== '')
    .map(chunk => {
      // The message ends at GS; the shortstat, when there is one, follows it.
      const end = chunk.lastIndexOf(GS)
      const fields = end < 0 ? chunk : chunk.slice(0, end)
      const stat = end < 0 ? '' : chunk.slice(end + 1)
      const [sha = '', short = '', time = '', subject = '', ...body] = fields.split(US)

      return {
        sha,
        short,
        time: Number(time),
        subject: subject.trim(),
        body: body.join(US).replace(/\r/g, '').trim().slice(0, BODY_LIMIT),
        added: countOf(stat, /(\d+) insertions?\(\+\)/),
        deleted: countOf(stat, /(\d+) deletions?\(-\)/),
      }
    })
    .filter(commit => commit.sha !== '' && Number.isFinite(commit.time))
    .reverse()

/** `git diff --numstat -z --no-renames`: `added TAB deleted TAB path NUL` per file. */
export const parseNumstat = (stdout: string): GitDiffStat => {
  const files: GitDiffFile[] = stdout
    .split('\0')
    .filter(record => record !== '')
    .map(record => {
      const [added = '', deleted = '', ...path] = record.split('\t')

      return {
        path: path.join('\t'),
        added: added === '-' ? null : Number(added),
        deleted: deleted === '-' ? null : Number(deleted),
      }
    })

  return {
    files,
    added: files.reduce((sum, file) => sum + (file.added ?? 0), 0),
    deleted: files.reduce((sum, file) => sum + (file.deleted ?? 0), 0),
  }
}

/** `git for-each-ref` with REF_FORMAT; symbolic refs (`origin/HEAD`) left out. */
export const parseBranches = (stdout: string): GitDiffBranch[] =>
  stdout
    .split(/\r?\n/)
    .map(line => line.split(US))
    .filter(([refname = '', , , symref = '']) => refname !== '' && symref === '')
    .map(([refname = '', name = '', time = '']) => ({
      name,
      time: Number(time) || 0,
      isRemote: refname.startsWith('refs/remotes/'),
    }))

/** `git rev-list --left-right --count base...compare`: the base's own commits, then the compare's. */
export const parseLeftRight = (stdout: string) => {
  const [behind = '0', ahead = '0'] = stdout.trim().split(/\s+/)

  return { behind: Number(behind) || 0, ahead: Number(ahead) || 0 }
}

/** A hunk whose lines were cut: its header counted again from what is left. */
const recount = ([header = '', ...body]: string[]): string[] => {
  const match = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/.exec(header)

  if (match === null) {
    return [header, ...body]
  }

  const old = body.filter(line => line.startsWith(' ') || line.startsWith('-')).length
  const now = body.filter(line => line.startsWith(' ') || line.startsWith('+')).length

  return [`@@ -${match[1]},${old} +${match[2]},${now} @@${match[3]}`, ...body]
}

/**
 * One file's `git diff` as a Code element takes it: the hunks alone, without control
 * characters, whole hunks up to `limit` characters (the first one cut to fit if it must).
 */
export const toHunks = (diff: string, limit = PATCH_LIMIT): Omit<GitDiffPatch, 'path'> => {
  const lines = diff.replace(/\r/g, '').replace(CONTROL, '�').split('\n')
  const first = lines.findIndex(line => line.startsWith('@@'))

  if (first < 0) {
    return { hunks: '', isCut: false, note: /^Binary files /m.test(diff) ? 'binary' : 'empty' }
  }

  const body = lines.slice(first)

  while (body.length > 0 && body[body.length - 1] === '') {
    body.pop()
  }

  const hunks: string[][] = []

  for (const line of body) {
    if (line.startsWith('@@') || hunks.length === 0) {
      hunks.push([line])
    } else {
      hunks[hunks.length - 1]!.push(line)
    }
  }

  const kept: string[] = []
  let size = 0

  for (const hunk of hunks) {
    const text = hunk.join('\n')
    const extra = (kept.length === 0 ? 0 : 1) + text.length

    if (size + extra <= limit) {
      kept.push(text)
      size += extra
      continue
    }

    if (kept.length === 0) {
      const head = [hunk[0] ?? '']
      let headSize = head[0]!.length

      for (const line of hunk.slice(1)) {
        if (headSize + 1 + line.length > limit) {
          break
        }

        head.push(line)
        headSize += 1 + line.length
      }

      kept.push(recount(head).join('\n'))
    }

    return { hunks: kept.join('\n'), isCut: true, note: '' }
  }

  return { hunks: kept.join('\n'), isCut: false, note: '' }
}

const empty = (status: Loaded['status'], message: string, branch = ''): Loaded => ({
  status,
  message,
  branch,
  commits: [],
  hasWorking: false,
  untracked: 0,
  baseOfOldest: '',
  branches: [],
  defaultBase: '',
})

const pickDefaultBase = (originHead: string, branches: GitDiffBranch[]) => {
  const names = new Set(branches.map(branch => branch.name))

  if (names.has(originHead)) {
    return originHead
  }

  return MAIN_BRANCHES.find(name => names.has(name)) ?? branches[0]?.name ?? ''
}

/** What the oldest commit is compared with: its first parent, or the empty tree for a root. */
const baseOf = async (run: Run, oldest: GitDiffCommit) => {
  const parent = await run(['git', 'rev-parse', '--verify', '--quiet', `${oldest.sha}^`])

  if (parent.exitCode === 0 && parent.stdout.trim() !== '') {
    return parent.stdout.trim()
  }

  const format = await run(['git', 'rev-parse', '--show-object-format'])

  return format.stdout.trim() === 'sha256' ? EMPTY_TREE.sha256 : EMPTY_TREE.sha1
}

export const loadTimeline = async (run: Run): Promise<Loaded> => {
  const inside = await run(['git', 'rev-parse', '--is-inside-work-tree'])

  if (inside.exitCode !== 0 || inside.stdout.trim() !== 'true') {
    return empty('no-repo', firstLine(inside.stderr) || 'Not a git repository')
  }

  const [branchRun, head, dirty, others, refs, originHead] = await Promise.all([
    run(['git', 'branch', '--show-current']),
    run(['git', 'rev-parse', '--verify', '--quiet', 'HEAD']),
    run(['git', ...NUMSTAT, 'HEAD', '--']),
    run(['git', 'ls-files', '--others', '--exclude-standard', '-z']),
    run(['git', 'for-each-ref', '--sort=-committerdate', REF_FORMAT, 'refs/heads', 'refs/remotes']),
    run(['git', 'symbolic-ref', '-q', '--short', 'refs/remotes/origin/HEAD']),
  ])
  const branch = branchRun.stdout.trim() || 'detached HEAD'

  if (head.exitCode !== 0) {
    return empty('no-commits', `No commits yet on ${branch}`, branch)
  }

  // First parent only: a merged pull request is one commit, so each step is one pull request's diff.
  const log = await run(['git', 'log', '--first-parent', '-n', String(LOG_LIMIT), LOG_FORMAT, '--shortstat'])

  if (log.exitCode !== 0) {
    return empty('error', firstLine(log.stderr) || 'git log failed', branch)
  }

  const commits = parseLog(log.stdout)
  const branches = refs.exitCode === 0 ? parseBranches(refs.stdout) : []
  const oldest = commits[0]

  return {
    status: 'ready',
    message: '',
    branch,
    commits,
    hasWorking: dirty.exitCode === 0 && dirty.stdout !== '',
    untracked: others.exitCode === 0 ? others.stdout.split('\0').filter(path => path !== '').length : 0,
    baseOfOldest: oldest === undefined ? '' : await baseOf(run, oldest),
    branches,
    defaultBase: pickDefaultBase(originHead.exitCode === 0 ? originHead.stdout.trim() : '', branches),
  }
}

/** The files a diff of `spec` changes. */
export const loadStat = async (run: Run, spec: Spec): Promise<GitDiffStat> => {
  const result = await run(['git', ...NUMSTAT, ...spec, '--'])

  if (result.exitCode !== 0) {
    throw new Error(firstLine(result.stderr) || 'git diff failed')
  }

  return parseNumstat(result.stdout)
}

/** One file's diff of `spec`, as hunks; a failure is kept as the note. */
export const loadPatch = async (run: Run, spec: Spec, path: string): Promise<GitDiffPatch> => {
  const result = await run(['git', ...PATCH, ...spec, '--', path])

  if (result.exitCode !== 0) {
    return { path, hunks: '', isCut: false, note: firstLine(result.stderr) || 'git diff failed' }
  }

  return { path, ...toHunks(result.stdout) }
}

/** How far apart two branches are: each side's own commits, and where they split. */
export const loadBranchCompare = async (run: Run, base: string, compare: string): Promise<GitDiffBranchCompare> => {
  const side = (range: string) =>
    run(['git', 'log', '--first-parent', '-n', String(BRANCH_COMMITS), LOG_FORMAT, '--shortstat', range])
  const [counts, mergeBase, aheadLog, behindLog] = await Promise.all([
    run(['git', 'rev-list', '--left-right', '--count', `${base}...${compare}`]),
    run(['git', 'merge-base', base, compare]),
    side(`${base}..${compare}`),
    side(`${compare}..${base}`),
  ])

  if (counts.exitCode !== 0) {
    throw new Error(firstLine(counts.stderr) || 'git rev-list failed')
  }

  const baseSha = mergeBase.exitCode === 0 ? mergeBase.stdout.trim() : ''
  const baseLog = baseSha === '' ? null : await run(['git', 'log', '-1', LOG_FORMAT, baseSha])

  return {
    ...parseLeftRight(counts.stdout),
    mergeBase: baseLog === null || baseLog.exitCode !== 0 ? null : (parseLog(baseLog.stdout)[0] ?? null),
    aheadCommits: aheadLog.exitCode === 0 ? parseLog(aheadLog.stdout) : [],
    behindCommits: behindLog.exitCode === 0 ? parseLog(behindLog.stdout) : [],
  }
}

